def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'
    if n == 5:
        return 'D'
    if n == 6:
        return 'C'

    retaliated = False
    if n >= 7 and history[6][1] == 'D':
        retaliated = True

    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining == 2:
        if retaliated:
            return 'C'
        else:
            return 'D'
    if remaining == 3:
        if retaliated:
            return 'C'
        else:
            return 'D'

    opp_last = history[-1][1]
    if retaliated:
        if opp_last == 'D':
            if n >= 2 and history[-2][1] == 'D':
                return 'D'
            else:
                return 'C'
        else:
            return 'C'
    else:
        if opp_last == 'D':
            return 'D'
        if n % 5 == 0:
            return 'D'
        return 'C'
